    },
    {
      "card_ids": ["C11"],
      "claim": "Ex vivo biodistribution in mice demonstrated moderate brain uptake of 3.60% ID/g at 2 min with rapid washout, consistent with meaningful BBB penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Direct brain/plasma measurements in mice showed brain concentrations approximately 50–60% of plasma levels for up to 8 hours, confirming sustained CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues demonstrate meaningful BBB/CNS penetration across multiple species and assay types, supporting adequate CNS access for the query molecule.",
